"use client";
import {useCallback,useEffect,useLayoutEffect,useRef,useState} from "react";
import {api,requestId,acknowledgeRequest,workspacePath,type Schema} from "../lib/api";
import {DraftStatus,flushDrafts,navigationBarrier,useDraft} from "../lib/drafts";
import {emptyCell,useBoardDraft,type CellData} from "../lib/board-drafts";
import {cellGuidance} from "../lib/board-guidance";
import {canonical,highlightParts} from "../lib/helpers";
import {assertHandoffPreparation,type ComparisonHandoff} from "../lib/comparison-handoff";
import {comparisonTablePosition} from "../lib/comparison-passage";
import {matchesPaperOrigin} from "../lib/paper-origin";
import {ExternalLink,Failure,Notice,Time} from "./ui";
import {CellProposals,ProposalControls} from "./cell-proposals";
import {BoardRetrievalProfile,retainedExplicitRequirements,type BoardProfile,type ComponentRequirements} from "./board-retrieval-profile";
import {BoardCandidates,type BoardCandidateResult} from "./board-candidates";
import type {Navigate} from "./workspace-app";
import {cellReviewSteps,derivedCellStep,sameExcerpt,type CellReviewStep} from "../lib/cell-review";
import RetainedExcerpt from "./retained-excerpt";
