  const [step,setStep]=useState<CellReviewStep>(requestedPassage?"evidence":"evidence"),[commentFocus,setCommentFocus]=useState(0);
  const commentInput=useRef<HTMLTextAreaElement>(null),initializedStep=useRef(false),actionPending=useRef(false);
