  async function revise(keep=false){await action(async()=>{await reload();const latest=await api<View>(endpoint);if(latest.definition.revision_id!==definition.revision_id||latest.freshness!=="current")throw new Error("Board dependencies changed. Reopen the latest definition; your edits remain retained.");const latestHead=latest.cells.find(cell=>cell.paper_id===paperId&&cell.field_id===fieldId)?.head??null;await draft.rebase(keep?draft.data:fromHead(latestHead),latestHead?.id??null);setEditing(true);setSavedRevision(null);setAttempted(false);await moveTo("comment",true);});}
